import { COURIER_STATUS_ACTIONS } from './actions'

export const INITIAL_STATE = {}

const reducer = (state = INITIAL_STATE, action) => {
  const { type, payload = {} } = action
  switch (type) {
    case COURIER_STATUS_ACTIONS.GET_COURIER_STATUS:
      return {
        ...state,
        ...payload
      }
    default:
      return state
  }
}

export default reducer
