import { resetError, updateLoader, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Container, CustomText } from '../../../../components'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../lang'
import { CourierTrackingStyle } from './index.style'
import { useGetCourierStatus } from '../state/hooks/useCourierTracking'
import { useEffect } from 'react'
import ShowSnackbar from '../../../../components/ShowNotification'
import Trackingbar from '../../../../components/Trackingbar'
import { getParamsFromUri } from '../../../../helpers/utility'
import get from 'lodash/get'
import moment from 'moment'

function CourierTracking (props) {
  const policyId = getParamsFromUri.call({ props }, 'policyId')
  const courierId = getParamsFromUri.call({ props }, 'courierId')

  const [{
    GET_COURIER_STATUS_LOADER
  }, dispatchLoader
  ] = useLoaderContextValue()

  const [
    {
      GET_COURIER_STATUS_ERROR, getCourierStatusStatus
    },
    dispatchError
  ] = useErrorContextValue()

  const [{ getCourierStatusData = {} }, getCourierStatusRequest] = useGetCourierStatus()

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        GET_COURIER_STATUS_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  useEffect(() => {
    if (GET_COURIER_STATUS_LOADER === undefined) {
      getCourierStatusRequest({
        policyId,
        query: {
          courier_id: courierId
        }
      })
    }
  }, [getCourierStatusRequest, GET_COURIER_STATUS_LOADER,
    policyId, courierId
  ])

  useEffect(() => {
    if (GET_COURIER_STATUS_ERROR && getCourierStatusStatus) {
      ShowSnackbar.error({
        visible: true,
        text: getCourierStatusStatus
      })
      dispatchError(resetError({
        getCourierStatusStatus: ''
      }))
    }
  }, [GET_COURIER_STATUS_ERROR, getCourierStatusStatus,
    dispatchError
  ])

  const trackingHistory = get(getCourierStatusData, 'tracking_history', [])

  return (
    <Container
      title={LANG_STRINGS.trackDelivery}
      displayBackButton
      loader={GET_COURIER_STATUS_LOADER}
      backBtnId='back_track_delivery'
      className='bg-white'
    >
      <CourierTrackingStyle>
        <CustomText
          size='10px'
          color={AgentColorPallette.black}
          className='refresh-bar'
          weight={700}
        >
          {LANG_STRINGS.pullDownToRefresh}
        </CustomText>
        <div className='tracker'>
          {
            trackingHistory.map((trackData, i) => {
              const title = moment(trackData.timestamp, moment.ISO_8601).format('DD/MM/YYYY, HH:mm')
              const titleColor = AgentColorPallette.black
              const subTitle = trackData.message
              const subTitleColor = (i === 0) ? AgentColorPallette.greenDarker : AgentColorPallette.black
              const upperBarColor = (i === 1) ? AgentColorPallette.greenDarker : AgentColorPallette.black
              const bottomBarColor = (i === 0) ? AgentColorPallette.greenDarker : AgentColorPallette.black
              const circleColor = (i === 0) ? AgentColorPallette.greenDarker : AgentColorPallette.black
              const hideBottomBar = (i === (trackingHistory.length - 1))
              const hideTopBar = (i === 0)
              return (
                <Trackingbar
                  key={`track_${i}`}
                  className='trackbar-border'
                  title={title}
                  titleColor={titleColor}
                  subTitleColor={subTitleColor}
                  subTitle={subTitle}
                  upperBarColor={upperBarColor}
                  bottomBarColor={bottomBarColor}
                  circleColor={circleColor}
                  hideBottomBar={hideBottomBar}
                  hideTopBar={hideTopBar}
                />
              )
            })
          }
        </div>
        <ShowSnackbar hideOkay />
      </CourierTrackingStyle>
    </Container>
  )
}

export default CourierTracking
