import { ConfigUrl } from '../../../../configs/url'

export const COURIER_STATUS_ACTIONS = {
  GET_COURIER_STATUS_REQUEST: 'GET_COURIER_STATUS_REQUEST',
  GET_COURIER_STATUS: 'GET_COURIER_STATUS'
}

export const getCourierStatus = (payload) => ({
  type: COURIER_STATUS_ACTIONS.GET_COURIER_STATUS_REQUEST,
  payload: {
    ...payload,
    method: 'get',
    url: ConfigUrl.courierTracking(payload.policyId)
  }
})
