import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCourierTrackingStateValue } from '../../context'
import { getCourierStatus } from '../actions'

export const useCourierTrackingServiceCall = (actionsCall = () => {}) => {
  const [courierState, dispatch] = useCourierTrackingStateValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }

  return [courierState, request]
}
export const useGetCourierStatus = () => useCourierTrackingServiceCall(getCourierStatus)
