import { Row } from '../../commonStyle/index.style'
import { CustomText } from '..'
import { AgentColorPallette } from '../../configs/colorPallete'
import { TrackingbarStyle } from './index.style'
import PropTypes from 'prop-types'

function Trackingbar (props) {
  const {
    className = '', upperBarColor = '',
    bottomBarColor = '', circleColor = '',
    hideBottomBar = false, hideTopBar = false
  } = props

  return (
    <TrackingbarStyle
      upperBarColor={upperBarColor}
      bottomBarColor={bottomBarColor}
      circleColor={circleColor}
      className={className}
      hideBottomBar={hideBottomBar}
      hideTopBar={hideTopBar}
    >
      <Row align='center' className='order-tracking-step'>
        <div className='order-tracking-status'>
          <span className='order-track-status-line upper-bar' />
          <span className='order-track-status-dot' />
          <span className='order-track-status-line bottom-bar' />
        </div>
        <div className='order-tracking-text'>
          <div>
            <CustomText
              color={props.titleColor || AgentColorPallette.fontDarkerGrey}
              size='10px'
            >
              {props.title}
            </CustomText>
            <CustomText
              color={props.subTitleColor || AgentColorPallette.regular}
              size='10px'
            >
              {props.subTitle}
            </CustomText>
          </div>
        </div>
      </Row>
    </TrackingbarStyle>
  )
}

Trackingbar.propTypes = {
  title: PropTypes.string,
  titleColor: PropTypes.string,
  subTitle: PropTypes.string,
  subTitleColor: PropTypes.string,
  upperBarColor: PropTypes.string,
  bottomBarColor: PropTypes.string,
  circleColor: PropTypes.string,
  hideBottomBar: PropTypes.bool,
  hideTopBar: PropTypes.bool
}

export default Trackingbar
